def transform(grid):
    """Align every colored pattern vertically with the color-8 pattern."""
    h, w = len(grid), len(grid[0])
    cells_by_color = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                cells_by_color.setdefault(value, []).append((r, c))
    anchor_top = min(r for r, _ in cells_by_color[8])
    out = [[0] * w for _ in range(h)]
    for color, cells in cells_by_color.items():
        dr = anchor_top - min(r for r, _ in cells)
        for r, c in cells:
            out[r + dr][c] = color
    return out
